{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.inv_l30dS_SKU_level AS WITH meta_map AS ( SELECT UPPER(IFF( UPPER(REPLACE(SKU_GROUP,\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP,\' \',\'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',1)||\'-\'||SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',2), SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',1) )) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta1 END), MIN(meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta2 END), MIN(meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta3 END), MIN(meta3) ) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), sales_b2c AS ( SELECT date, sku_group, CASE WHEN type=\'Shopify\' THEN \'SHOPIFY\' WHEN type=\'Marketplace\' THEN \'MP\' WHEN type=\'Store\' THEN \'OFFLINE\' END AS channel, SUM(gross_sales::FLOAT) AS revenue, SUM(gross_quantity::INT) AS sales_qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1,2,3 ), sales_sor AS ( SELECT TO_DATE(order_created_date,\'YYYYMMDD\') AS date, style_ AS sku_group, \'MP\' AS channel, SUM(TRY_TO_NUMBER(REPLACE(revenue,\',\',\'\'))) AS revenue, SUM(TRY_TO_NUMBER(REPLACE(sales,\',\',\'\'))) AS sales_qty FROM snitch_db.maplemonk.mp_sor_sales_myntra WHERE order_created_date >= 20230101 GROUP BY 1,2,3 UNION ALL SELECT TO_DATE(order_date_key,\'YYYYMMDD\'), style_, \'MP\', SUM(TRY_TO_NUMBER(REPLACE(sp_per_unit_,\',\',\'\'))*TRY_TO_NUMBER(REPLACE(units,\',\',\'\'))), SUM(TRY_TO_NUMBER(REPLACE(units,\',\',\'\'))) FROM snitch_db.maplemonk.mp_sor_sales_flipkart GROUP BY 1,2,3 ), sales_fact AS ( SELECT date, sku_group, SUM(revenue) AS revenue, SUM(sales_qty) AS sales_qty, SUM(CASE WHEN channel=\'SHOPIFY\' THEN revenue ELSE 0 END) AS shopify_revenue, SUM(CASE WHEN channel=\'SHOPIFY\' THEN sales_qty ELSE 0 END) AS shopify_sales_qty, SUM(CASE WHEN channel=\'MP\' THEN revenue ELSE 0 END) AS mp_revenue, SUM(CASE WHEN channel=\'MP\' THEN sales_qty ELSE 0 END) AS mp_sales_qty, SUM(CASE WHEN channel=\'OFFLINE\' THEN revenue ELSE 0 END) AS offline_revenue, SUM(CASE WHEN channel=\'OFFLINE\' THEN sales_qty ELSE 0 END) AS offline_sales_qty FROM ( SELECT date, sku_group, channel, revenue, sales_qty FROM sales_b2c UNION ALL SELECT date, sku_group, channel, revenue, sales_qty FROM sales_sor ) GROUP BY 1,2 ), overall_returns_fact AS ( SELECT \"PUTAWAY_UPDATED\"::DATE AS date, UPPER(TRIM(REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\',REVERSE(\"Item Type skuCode\"))+1, LEN(\"Item Type skuCode\") )))) AS sku_group, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS overall_returns_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'b2c return%\' GROUP BY 1,2 ), shopify_returns_fact AS ( SELECT order_date::DATE AS date, sku_group, SUM(return_qty) AS shopify_returns_qty FROM snitch_db.maplemonk.return_fact_items WHERE reason NOT IN (\'not_returned\') GROUP BY 1,2 ), inward_fact AS ( SELECT \"PUTAWAY_UPDATED\"::DATE AS date, UPPER(TRIM(REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\',REVERSE(\"Item Type skuCode\"))+1, LEN(\"Item Type skuCode\") )))) AS sku_group, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1,2 ), clicks_fact AS ( SELECT ga_date::DATE AS date, sku_group, SUM(clicks) AS clicks FROM snitch_db.maplemonk.clicks_itemid GROUP BY 1,2 ), inventory_fact AS ( SELECT date, sku_group, SUM(wh_qty) AS wh_inventory_qty, SUM(store_qty + jit_qty) AS store_jit_inventory_qty, SUM(total_qty) AS inventory_qty FROM snitch_db.maplemonk.inv_logs GROUP BY 1, 2 ), store_count_fact AS ( SELECT delivered_date::DATE AS date, sku_group, COUNT(DISTINCT marketplace_mapped) AS stores_selling_count FROM snitch_db.maplemonk.store_fact_items_offline WHERE UPPER(marketplace_mapped) NOT IN ( \'SNITCH - WH - NORTH\',\'SNITCH - WH - YELHANKA 2\',\'SNITCH - WH - YELHANKA\' ) GROUP BY 1,2 ), sellable_fact AS ( SELECT fs.date, fs.sku_group, CASE WHEN fs.total_online_remark = \'Full Size Inv\' AND COALESCE(fa.weighted_age_days, 999) < 180 THEN COALESCE(fs.final_wh_qty, 0) ELSE 0 END AS wh_sellable_qty, CASE WHEN fs.total_remark = \'Full Size Inv\' AND COALESCE(fa.weighted_age_days, 999) < 180 THEN COALESCE(fs.final_wh_qty, 0) ELSE 0 END AS wh_allocatable_qty, CASE WHEN fs.total_remark = \'Full Size Inv\' AND COALESCE(fa.weighted_age_days, 999) < 180 THEN COALESCE(fs.final_store_jit_qty, 0) ELSE 0 END AS store_jit_sellable_qty, CASE WHEN fs.total_remark = \'Full Size Inv\' AND COALESCE(fa.weighted_age_days, 999) < 180 THEN COALESCE(fs.final_total_qty, 0) ELSE 0 END AS overall_sellable_qty FROM snitch_db.maplemonk.full_size_inv_avail fs LEFT JOIN snitch_db.maplemonk.daily_fifo_ageing fa ON fa.date = fs.date AND fa.sku_group = fs.sku_group ), base_spine AS ( SELECT date, sku_group FROM sales_fact UNION SELECT date, sku_group FROM overall_returns_fact UNION SELECT date, sku_group FROM shopify_returns_fact UNION SELECT date, sku_group FROM inward_fact UNION SELECT date, sku_group FROM clicks_fact UNION SELECT date, sku_group FROM inventory_fact UNION SELECT date, sku_group FROM store_count_fact UNION SELECT date, sku_group FROM sellable_fact ), daily_grain AS ( SELECT bs.date, bs.sku_group, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, mm.cogs, COALESCE(inv.inventory_qty, 0) AS inventory_qty, COALESCE(inv.inventory_qty,0) * COALESCE(mm.cogs,0) AS inventory_cogs_value, COALESCE(inv.wh_inventory_qty, 0) AS wh_inventory_qty, COALESCE(inv.store_jit_inventory_qty,0) AS store_jit_inventory_qty, sl.wh_sellable_qty, sl.wh_allocatable_qty, sl.store_jit_sellable_qty, sl.overall_sellable_qty, COALESCE(sf.revenue, 0) AS revenue, COALESCE(sf.sales_qty, 0) AS sales_qty, COALESCE(sf.sales_qty, 0) * COALESCE(mm.cogs,0) AS sales_cogs, COALESCE(sf.shopify_revenue, 0) AS shopify_revenue, COALESCE(sf.shopify_sales_qty, 0) AS shopify_sales_qty, COALESCE(sf.shopify_sales_qty, 0)*COALESCE(mm.cogs,0) AS shopify_sales_cogs, COALESCE(sf.mp_revenue, 0) AS mp_revenue, COALESCE(sf.mp_sales_qty, 0) AS mp_sales_qty, COALESCE(sf.mp_sales_qty, 0)*COALESCE(mm.cogs,0) AS mp_sales_cogs, COALESCE(sf.offline_revenue, 0) AS offline_revenue, COALESCE(sf.offline_sales_qty, 0) AS offline_sales_qty, COALESCE(sf.offline_sales_qty, 0)*COALESCE(mm.cogs,0) AS offline_sales_cogs, COALESCE(orf.overall_returns_qty, 0) AS overall_returns_qty, COALESCE(orf.overall_returns_qty,0)*COALESCE(mm.cogs,0) AS overall_returns_cogs, COALESCE(srf.shopify_returns_qty, 0) AS shopify_returns_qty, COALESCE(srf.shopify_returns_qty,0)*COALESCE(mm.cogs,0) AS shopify_returns_cogs, COALESCE(ifw.inward_qty, 0) AS inward_qty, COALESCE(ifw.inward_qty,0)*COALESCE(mm.cogs,0) AS inward_cogs, COALESCE(cf.clicks, 0) AS clicks, COALESCE(sc.stores_selling_count, 0) AS stores_selling_count FROM base_spine bs LEFT JOIN inventory_fact inv ON bs.sku_group = inv.sku_group AND bs.date = inv.date LEFT JOIN sales_fact sf ON bs.sku_group = sf.sku_group AND bs.date = sf.date LEFT JOIN overall_returns_fact orf ON bs.sku_group = orf.sku_group AND bs.date = orf.date LEFT JOIN shopify_returns_fact srf ON bs.sku_group = srf.sku_group AND bs.date = srf.date LEFT JOIN inward_fact ifw ON bs.sku_group = ifw.sku_group AND bs.date = ifw.date LEFT JOIN clicks_fact cf ON bs.sku_group = cf.sku_group AND bs.date = cf.date LEFT JOIN store_count_fact sc ON bs.sku_group = sc.sku_group AND bs.date = sc.date LEFT JOIN sellable_fact sl ON bs.sku_group = sl.sku_group AND bs.date = sl.date LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER(IFF( UPPER(REPLACE(bs.sku_group,\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(bs.sku_group,\' \',\'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(bs.sku_group,\' \',\'\'),\'-\',1)||\'-\'||SPLIT_PART(REPLACE(bs.sku_group,\' \',\'\'),\'-\',2), SPLIT_PART(REPLACE(bs.sku_group,\' \',\'\'),\'-\',1) )) ), ff AS ( SELECT date, sku_group, l1_category, category, meta1, meta2, meta3, inventory_qty, inventory_cogs_value, wh_inventory_qty, store_jit_inventory_qty, wh_sellable_qty, wh_allocatable_qty, store_jit_sellable_qty, overall_sellable_qty, revenue, sales_qty, sales_cogs, shopify_revenue, shopify_sales_qty, shopify_sales_cogs, mp_revenue, mp_sales_qty, mp_sales_cogs, offline_revenue, offline_sales_qty, offline_sales_cogs, overall_returns_qty, overall_returns_cogs, shopify_returns_qty, shopify_returns_cogs, inward_qty, inward_cogs, clicks, stores_selling_count, SUM(revenue) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_revenue, SUM(sales_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_sales_qty, SUM(sales_cogs) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_sales_cogs, SUM(shopify_revenue) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_shopify_revenue, SUM(shopify_sales_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_shopify_sales_qty, SUM(shopify_sales_cogs) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_shopify_sales_cogs, SUM(mp_revenue) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_mp_revenue, SUM(mp_sales_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_mp_sales_qty, SUM(mp_sales_cogs) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_mp_sales_cogs, SUM(offline_revenue) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_offline_revenue, SUM(offline_sales_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_offline_sales_qty, SUM(offline_sales_cogs) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_offline_sales_cogs, SUM(overall_returns_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_overall_returns_qty, SUM(overall_returns_cogs) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_overall_returns_cogs, SUM(shopify_returns_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_shopify_returns_qty, SUM(shopify_returns_cogs) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_shopify_returns_cogs, SUM(inward_qty) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_inward_qty, SUM(inward_cogs) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_inward_cogs, SUM(clicks) OVER (PARTITION BY sku_group ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_clicks FROM daily_grain ORDER BY sku_group, date ) SELECT * FROM ff ;",
                    "transaction": true
                }
            ) }}
